export function getItineraryDayTranslation(textOrKey: string, locale: string): string | null {
  if (!textOrKey) return null;
  const entry = ITINERARY_DAY_TRANSLATIONS[textOrKey];
  if (entry && entry[locale]) return entry[locale];
  return null;
}

export function getItineraryDayDescription(tourId: string | undefined, day: number, locale: string): string | null {
  if (!tourId) return null;
  const key = `${tourId}_day_${day}_desc`;
  const entry = ITINERARY_DAY_TRANSLATIONS[key];
  if (entry && entry[locale]) return entry[locale];
  return null;
}

export function getItineraryDayTitle(tourId: string | undefined, day: number, locale: string): string | null {
  if (!tourId) return null;
  const key = `${tourId}_day_${day}_title`;
  const entry = ITINERARY_DAY_TRANSLATIONS[key];
  if (entry && entry[locale]) return entry[locale];
  return null;
}
